// Each of four slots reports its actual answering source after fallback. The
// upstream card's 6s report race is deliberately omitted: completion means all
// source chains settled. Stop cancels fetches and not-yet-started slot timers.
export async function runMyIPDns(signal, onSource) {
  const host = createRun(signal);
  const results = [];
  const emit = row => {
    results[row.slot] = row;
    onSource?.({ ...row, ...(row.attemptedSources ? { attemptedSources: [...row.attemptedSources] } : {}) });
  };
  const cancelled = (slot, source) => ({ slot, sourceId: source.id, sourceName: source.name,
    status: 'cancelled', note: '已停止，未完成此来源采样' });
  try {
    await Promise.all(MYIP_DNS_PROVIDERS.map(async (source, slot) => {
      if (!(await host.wait(slot * 200)) || signal.aborted) {
        emit(cancelled(slot, source)); return;
      }
      emit({ slot, sourceId: source.id, sourceName: source.name,
        status: 'running', note: '正在采样；失败时按 IPCheck.ing 原流程重试及切换来源' });
      try {
        const { ip, provider } = await host.run(slot);
        if (signal.aborted) { emit(cancelled(slot, source)); return; }
        const chain = host.chain(slot);
        const answered = chain.findIndex(candidate => candidate.id === provider.id);
        emit({ slot, sourceId: provider.id, sourceName: provider.name, status: 'ready',
          address: ip, note: '已观察到此来源记录的代表解析出口',
          attemptedSources: chain.slice(0, answered + 1).map(candidate => candidate.id) });
      } catch (error) {
        if (signal.aborted) { emit(cancelled(slot, source)); return; }
        emit({ slot, sourceId: source.id, sourceName: source.name, status: 'unavailable',
          note: error?.name === 'AbortError' ? '来源请求超时，所有重试及备用来源均未取得结果'
            : '此来源及备用来源未取得有效解析器地址',
          attemptedSources: host.chain(slot).map(candidate => candidate.id) });
      }
    }));
    return results;
  } finally {
    host.cleanup();
  }
}
